package com.citacloud.springboot.contacloud.app.views;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.multitenancy.*;import com.citacloud.springboot.contacloud.app.security.TenantContext;import com.citacloud.springboot.contacloud.app.services.*;import com.citacloud.springboot.contacloud.app.views.components.*;
import com.vaadin.flow.component.Component;import com.vaadin.flow.component.checkbox.Checkbox;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.confirmdialog.ConfirmDialog;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.radiobutton.RadioButtonGroup;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.data.value.ValueChangeMode;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;import org.springframework.beans.factory.ObjectProvider;import java.util.*;import java.util.stream.Collectors;
@Route(value="empresas",layout=MainLayout.class) @PageTitle("Empresas | ContaCloud") @PermitAll
public class EmpresasView extends VerticalLayout implements BeforeEnterObserver {
    private final EmpresaAdministracionService service;private final EmpresaModuloService modules;private final TenantProvisioningService provisioning;private final DatabaseAllocationService allocation;private final AppGrid<EmpresaResumenDto> grid=new AppGrid<>(EmpresaResumenDto.class);private final TextField buscar=new TextField();private final ComboBox<String> estado=new ComboBox<>();private final AppPagination pagination;
    public EmpresasView(EmpresaAdministracionService service,EmpresaModuloService modules,ObjectProvider<TenantProvisioningService> provisioning,ObjectProvider<DatabaseAllocationService> allocation){this.service=service;this.modules=modules;this.provisioning=provisioning.getIfAvailable();this.allocation=allocation.getIfAvailable();addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();var nuevo=new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Nueva empresa",e->crear());nuevo.setVisible(has("empresas.crear"));add(new AppPageHeader("Empresas","Administra todas las empresas registradas.",nuevo));buscar.setLabel("Buscar");buscar.setPlaceholder("Nombre, código o identificación");buscar.setClearButtonVisible(true);buscar.setValueChangeMode(ValueChangeMode.LAZY);estado.setLabel("Estado");estado.setItems("Todos","Activas","Inactivas");estado.setValue("Todos");configurarGrid();pagination=new AppPagination(r->cargar());buscar.addValueChangeListener(e->{pagination.reset();cargar();});estado.addValueChangeListener(e->{if(pagination!=null){pagination.reset();cargar();}});var filtros=new HorizontalLayout(buscar,estado);filtros.addClassName("cc-filter-bar");filtros.setAlignItems(Alignment.END);add(filtros,grid,pagination);if(has("empresas.ver"))cargar();}
    @Override public void beforeEnter(BeforeEnterEvent event){if(!has("empresas.ver"))event.rerouteTo(DashboardView.class);}
    private void configurarGrid(){grid.addColumn(EmpresaResumenDto::codigo).setHeader("Código de acceso").setAutoWidth(true);grid.addColumn(EmpresaResumenDto::nombre).setHeader("Nombre comercial").setAutoWidth(true);grid.addColumn(EmpresaResumenDto::identificacionFiscal).setHeader("RNC / Identificación").setAutoWidth(true);grid.addColumn(EmpresaResumenDto::modulos).setHeader("Módulos").setAutoWidth(true);grid.addComponentColumn(e->badge(e.activo())).setHeader("Estado");grid.addComponentColumn(this::acciones).setHeader("Acciones").setAutoWidth(true).setFlexGrow(0);}
    private Component acciones(EmpresaResumenDto empresa){var row=new HorizontalLayout();row.setPadding(false);row.setSpacing(false);row.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver empresa",e->ver(empresa)));if(has("empresas.editar")||has("empresas.configurar_modulos")||has("empresas.resetear_contrasena"))row.add(new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar empresa",e->editarEmpresa(empresa)));if(empresa.activo()&&has("empresas.desactivar"))row.add(new AppActionButton(ActionType.DEACTIVATE,ButtonSize.GRID_ACTION,"Desactivar empresa",e->confirmarDesactivar(empresa)));if(!empresa.activo()&&has("empresas.activar"))row.add(new AppActionButton(ActionType.ACTIVATE,ButtonSize.GRID_ACTION,"Activar empresa",e->confirmarActivar(empresa)));return row;}
    private void cargar(){if(pagination==null)return;var r=pagination.currentRequest();Boolean active=switch(estado.getValue()==null?"Todos":estado.getValue()){case"Activas"->true;case"Inactivas"->false;default->null;};var page=service.buscar(buscar.getValue(),active,r.page(),r.size());grid.setItems(page.getContent());pagination.setTotal(page.getTotalElements());}
    private void crear(){var d=new Dialog();d.setHeaderTitle("Nueva empresa");d.setWidth("min(940px, 96vw)");var codigo=new TextField("Código de acceso");codigo.setRequired(true);codigo.setMaxLength(30);codigo.setAllowedCharPattern("[A-Za-z0-9._-]");codigo.setPlaceholder("Ej.: EMPRESA01");codigo.setHelperText("Se utilizará junto con el usuario y la contraseña para iniciar sesión.");var nombre=new TextField("Nombre comercial");nombre.setRequired(true);var razon=new TextField("Razón social");var rnc=new TextField("RNC / Identificación");var telefono=new TextField("Teléfono");var correo=new EmailField("Correo electrónico");var direccion=new TextArea("Dirección");direccion.addClassName("cc-dialog-span-2");var limitarUsuarios=new Checkbox("Limitar cantidad de usuarios",false);var limiteUsuarios=new IntegerField("Cantidad máxima de usuarios");limiteUsuarios.setMin(1);limiteUsuarios.setMax(100000);limiteUsuarios.setStepButtonsVisible(true);limiteUsuarios.setHelperText("Incluye el usuario administrador inicial.");limiteUsuarios.setVisible(false);limitarUsuarios.addValueChangeListener(e->{boolean habilitado=e.getValue();limiteUsuarios.setVisible(habilitado);limiteUsuarios.setRequiredIndicatorVisible(habilitado);if(!habilitado)limiteUsuarios.clear();});InputFieldSupport.desactivarAutocompletado(rnc,"nueva-empresa-rnc");InputFieldSupport.desactivarAutocompletado(telefono,"nueva-empresa-telefono");InputFieldSupport.aplicarFormatoRnc(rnc);InputFieldSupport.aplicarFormatoTelefono(telefono);var form=new Div(codigo,nombre,razon,rnc,telefono,correo,direccion,limitarUsuarios,limiteUsuarios);form.addClassName("cc-dialog-form");var usuario=new TextField("Usuario");usuario.setRequired(true);var nombreUsuario=new TextField("Nombre");nombreUsuario.setRequired(true);var apellidoUsuario=new TextField("Apellido");apellidoUsuario.setRequired(true);var correoUsuario=new EmailField("Correo del usuario");var telefonoUsuario=new TextField("Teléfono del usuario");var clave=new PasswordField("Contraseña");clave.setRequired(true);var confirmarClave=new PasswordField("Confirmar contraseña");confirmarClave.setRequired(true);InputFieldSupport.desactivarAutocompletado(usuario,"nuevo-tenant-usuario");InputFieldSupport.desactivarAutocompletado(telefonoUsuario,"nuevo-tenant-telefono");InputFieldSupport.nuevaContrasena(clave,"nuevo-tenant-clave");InputFieldSupport.nuevaContrasena(confirmarClave,"nuevo-tenant-confirmar-clave");InputFieldSupport.aplicarFormatoTelefono(telefonoUsuario);var userForm=new Div(usuario,nombreUsuario,apellidoUsuario,correoUsuario,telefonoUsuario,clave,confirmarClave);userForm.addClassName("cc-dialog-form");Map<String,Checkbox> checks=new LinkedHashMap<>();d.add(new H2("Datos de la empresa"),form,new H2("Usuario administrador"),new Paragraph("Será el único usuario inicial del nuevo tenant y no tendrá acceso al módulo Empresas."),userForm);if(has("empresas.configurar_modulos")){var moduleGrid=new Div();moduleGrid.addClassName("cc-company-module-grid");for(ModuloEmpresaDto m:modules.catalogoDisponible()){var c=new Checkbox(m.nombre(),m.core());c.setHelperText(m.descripcion());c.setEnabled(!m.core());checks.put(m.key(),c);moduleGrid.add(c);}d.add(new H2("Módulos y opciones"),moduleGrid);}
        boolean multiBase=provisioning!=null&&allocation!=null;var alojamiento=new Div();alojamiento.addClassName("cc-card");var ayuda=new Paragraph("Se creará un tenant independiente, sin usuarios ni accesos heredados del tenant actual.");var modo=new RadioButtonGroup<HostingMode>("Asignación de base");modo.setValue(HostingMode.AUTOMATIC);var nodo=new ComboBox<DatabaseNode>("Base disponible");if(multiBase){List<HostingMode> modos=new ArrayList<>();modos.add(HostingMode.AUTOMATIC);if(has("empresas.seleccionar_base")){modos.add(HostingMode.MANUAL);modos.add(HostingMode.DEDICATED);}modo.setItems(modos);modo.setItemLabelGenerator(x->switch(x){case AUTOMATIC->"Automática";case MANUAL->"Seleccionar base compartida";case DEDICATED->"Base dedicada";});nodo.setItemLabelGenerator(x->x.code()+" · "+x.name()+(x.region()==null?"":" · "+x.region()));nodo.setWidthFull();alojamiento.add(new H3("Nuevo tenant"),ayuda,modo,nodo);Runnable actualizarAlojamiento=()->{nodo.setVisible(modo.getValue()!=HostingMode.AUTOMATIC);if(nodo.isVisible()){nodo.clear();nodo.setItems(modo.getValue()==HostingMode.DEDICATED?allocation.eligibleDedicatedNodes():allocation.eligibleSharedNodes());}};modo.addValueChangeListener(e->actualizarAlojamiento.run());actualizarAlojamiento.run();}else alojamiento.add(new H3("Nuevo tenant"),ayuda,new Paragraph("Se alojará de forma aislada en la base de datos actual."));d.add(new H2("Alojamiento / Base de datos"),alojamiento);
        String idempotencyKey=UUID.randomUUID().toString();d.getFooter().add(new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",e->{try{Set<String> keys=checks.entrySet().stream().filter(x->x.getValue().getValue()).map(Map.Entry::getKey).collect(Collectors.toSet());NuevaEmpresaDto input=new NuevaEmpresaDto(codigo.getValue(),nombre.getValue(),razon.getValue(),rnc.getValue(),telefono.getValue(),correo.getValue(),direccion.getValue(),limitarUsuarios.getValue(),limiteUsuarios.getValue(),keys);UsuarioInicialDto userInput=new UsuarioInicialDto(usuario.getValue(),nombreUsuario.getValue(),apellidoUsuario.getValue(),correoUsuario.getValue(),telefonoUsuario.getValue());ProvisioningResult result;if(multiBase){DatabaseNode selected=nodo.getValue();if(modo.getValue()!=HostingMode.AUTOMATIC&&selected==null)throw new ReglaNegocioException("Seleccione una base de datos disponible.");result=provisioning.provision(new ProvisionTenantRequest(idempotencyKey,input,keys,modo.getValue(),selected==null?null:selected.id()),userInput,clave.getValue(),confirmarClave.getValue());}else result=service.crearTenantLocal(input,userInput,clave.getValue(),confirmarClave.getValue());d.close();notify("Tenant y empresa creados. Código: "+result.empresaCodigo()+" · Usuario: "+usuario.getValue()+" · Base: "+result.databaseNodeCode());}catch(RuntimeException ex){notify(ex.getMessage());}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}
    private void editarEmpresa(EmpresaResumenDto empresa){
        var detalle=service.obtener(empresa.id());var d=new Dialog();d.setHeaderTitle("Editar empresa");d.setWidth("min(940px, 96vw)");
        var nombre=campoTexto("Nombre comercial",detalle.nombreComercial());nombre.setRequired(true);nombre.setMaxLength(150);var razon=campoTexto("Razón social",detalle.razonSocial());var rnc=campoTexto("RNC / Identificación",InputFieldSupport.formatearRnc(valor(detalle.identificacionFiscal())));var telefono=campoTexto("Teléfono",InputFieldSupport.formatearTelefono(valor(detalle.telefono())));InputFieldSupport.aplicarFormatoRnc(rnc);InputFieldSupport.aplicarFormatoTelefono(telefono);var correo=campoCorreo("Correo electrónico",detalle.correo());var direccion=new TextArea("Dirección");direccion.setValue(valor(detalle.direccion()));direccion.addClassName("cc-dialog-span-2");var limitarUsuarios=new Checkbox("Limitar cantidad de usuarios",detalle.limiteUsuariosHabilitado());var limiteUsuarios=new IntegerField("Cantidad máxima de usuarios");limiteUsuarios.setMin(1);limiteUsuarios.setMax(100000);limiteUsuarios.setStepButtonsVisible(true);limiteUsuarios.setHelperText("Solo cuentan los usuarios activos.");limiteUsuarios.setVisible(detalle.limiteUsuariosHabilitado());if(detalle.limiteUsuarios()!=null)limiteUsuarios.setValue(detalle.limiteUsuarios());limitarUsuarios.addValueChangeListener(e->{boolean habilitado=e.getValue();limiteUsuarios.setVisible(habilitado);limiteUsuarios.setRequiredIndicatorVisible(habilitado);if(!habilitado)limiteUsuarios.clear();});
        boolean editarDatos=has("empresas.editar");List.of(nombre,razon,rnc,telefono,correo,direccion).forEach(c->c.setReadOnly(!editarDatos));limitarUsuarios.setReadOnly(!editarDatos);limiteUsuarios.setReadOnly(!editarDatos);var form=new Div(nombre,razon,rnc,telefono,correo,direccion,limitarUsuarios,limiteUsuarios);form.addClassName("cc-dialog-form");d.add(new H2("Datos de la empresa"),form);
        Map<String,Checkbox> checks=new LinkedHashMap<>();boolean configurarModulos=has("empresas.configurar_modulos");if(configurarModulos){var moduleGrid=new Div();moduleGrid.addClassName("cc-company-module-grid");for(ModuloEmpresaDto m:service.modulos(empresa.id())){var c=new Checkbox(m.nombre(),m.habilitado());c.setHelperText(m.descripcion());c.setEnabled(!m.core());checks.put(m.key(),c);moduleGrid.add(c);}d.add(new H2("Módulos y opciones"),moduleGrid);}
        if(has("empresas.resetear_contrasena")){var usuarioClave=new ComboBox<UsuarioEmpresaClaveDto>("Usuario");usuarioClave.setItems(service.usuariosParaReset(empresa.id()));usuarioClave.setItemLabelGenerator(u->u.usuario()+" · "+u.nombreCompleto()+(u.activo()?"":" · Inactivo"));usuarioClave.setWidthFull();var nuevaClave=new PasswordField("Nueva contraseña");var confirmarClave=new PasswordField("Confirmar contraseña");InputFieldSupport.nuevaContrasena(nuevaClave,"reset-empresa-clave");InputFieldSupport.nuevaContrasena(confirmarClave,"reset-empresa-confirmar-clave");var resetear=new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Restablecer contraseña",e->{try{UsuarioEmpresaClaveDto seleccionado=usuarioClave.getValue();service.resetearContrasena(empresa.id(),seleccionado==null?null:seleccionado.usuarioId(),nuevaClave.getValue(),confirmarClave.getValue());nuevaClave.clear();confirmarClave.clear();notify("Contraseña restablecida correctamente.");}catch(RuntimeException ex){notify(ex.getMessage());}});var resetForm=new Div(usuarioClave,nuevaClave,confirmarClave,resetear);resetForm.addClassName("cc-dialog-form");d.add(new H2("Restablecer contraseña"),new Paragraph("Esta acción modifica únicamente la contraseña del usuario seleccionado."),resetForm);}
        if(editarDatos||configurarModulos)d.getFooter().add(new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",e->{try{if(editarDatos)service.actualizar(empresa.id(),new ActualizarEmpresaDto(nombre.getValue(),razon.getValue(),rnc.getValue(),telefono.getValue(),correo.getValue(),direccion.getValue(),limitarUsuarios.getValue(),limiteUsuarios.getValue()));if(configurarModulos)service.configurarModulos(empresa.id(),checks.entrySet().stream().filter(x->x.getValue().getValue()).map(Map.Entry::getKey).collect(Collectors.toSet()));d.close();cargar();notify("Empresa actualizada correctamente.");}catch(RuntimeException ex){notify(ex.getMessage());}}));
        d.getFooter().add(new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();
    }
    private void ver(EmpresaResumenDto e){var d=new Dialog();d.setHeaderTitle("Detalle de empresa");d.add(new AppDetailSection("Información").field("Código de acceso",e.codigo()).field("Nombre comercial",e.nombre()).field("RNC / Identificación",e.identificacionFiscal()).field("Módulos habilitados",Long.toString(e.modulos())).field("Alojamiento",e.alojamiento()).field("Estado",e.activo()?"Activa":"Inactiva"));d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",x->d.close()));d.open();}
    private void confirmarDesactivar(EmpresaResumenDto e){var c=new ConfirmDialog();c.setHeader("Desactivar empresa");c.setText("Los datos se conservarán. ¿Desea desactivar "+e.nombre()+"?");c.setCancelable(true);c.setCancelText("Cancelar");c.setConfirmText("Desactivar");c.setConfirmButtonTheme("error primary");c.addConfirmListener(x->{try{service.desactivar(e.id());cargar();notify("Empresa desactivada.");}catch(RuntimeException ex){notify(ex.getMessage());}});c.open();}
    private void confirmarActivar(EmpresaResumenDto e){var c=new ConfirmDialog();c.setHeader("Activar empresa");c.setText("¿Desea activar "+e.nombre()+"?");c.setCancelable(true);c.setCancelText("Cancelar");c.setConfirmText("Activar");c.setConfirmButtonTheme("primary");c.addConfirmListener(x->{try{service.activar(e.id());cargar();notify("Empresa activada.");}catch(RuntimeException ex){notify(ex.getMessage());}});c.open();}
    static TextField campoTexto(String etiqueta,String contenido){var campo=new TextField(etiqueta);campo.setValue(valor(contenido));return campo;}
    static EmailField campoCorreo(String etiqueta,String contenido){var campo=new EmailField(etiqueta);campo.setValue(valor(contenido));return campo;}
    private static Span badge(boolean active){var s=new Span(active?"Activa":"Inactiva");s.getElement().getThemeList().add("badge "+(active?"success":"contrast"));return s;}private static String valor(String value){return value==null?"":value;}private static boolean has(String permission){return TenantContext.principalActual().permisos().contains(permission);}private static void notify(String text){com.vaadin.flow.component.notification.Notification.show(text==null?"No fue posible completar la operación.":text);}
}
